/* 中文讲解和练习为教学编写；页码对应课堂所列考点。 */
const LESSONS=[];
const section=(title,text,table=null,examples=[])=>({title,text:Array.isArray(text)?text:[text],table,examples});
const table=(headers,rows)=>({headers,rows});
const question=(topic,prompt,options,answer,explain)=>({topic,prompt,options,answer,explain});
const lesson=(id,unit,pages,title,summary,sections,questions)=>LESSONS.push({id,unit,pages,title,summary,sections,questions});
const persons=['io','tu','lui / lei / Lei','noi','voi','loro'];
const conjugation=(names,columns)=>table(['人称',...names],persons.map((p,i)=>[p,...columns.map(c=>c.split(',')[i])]));

lesson(32,6,[11,12,17],'程度、礼貌与接话：把笔记短句说对','补充 -issimo 的完整构成，并区分“我也喜欢”和“认识你很高兴”。',[
section('1. -issimo 不是只有 tantissimo 一个词',['笔记标出的 -issimo 是形容词绝对最高程度的一种常用构成。通常去掉形容词末元音，再加 -issimo：alto → altissimo，bello → bellissimo，gentile → gentilissimo。它表示“非常”，不是自动表示“某一组里最……”。','作为形容词，要跟名词配合：bellissimo / bellissima / bellissimi / bellissime。La casa è bellissima 与 Le case sono bellissime。修饰动作的 avverbio（副词）通常不这样随名词变，例如 Grazie tantissimo。']),
section('2. 很、太、极其：意思别混',['molto buono = 很好/很好吃；buonissimo = 非常好/非常好吃；troppo caro = 太贵，含超过合适程度。ottimo 也是 buono 的常见高程度形式；不要再机械叠加成 più ottimo。','un sacco 和 da morire 很口语：Mi piace un sacco / Mi piace da morire。写正式邮件时可用 Mi piace molto。Non mi piace per niente = 我一点也不喜欢。']),
section('3. “我也喜欢”与“幸会”是两回事',['Mi piace la pizza. — Anche a me. 这是表达相同喜好。Piacere! 则常用于初次见面，相当于“很高兴认识你”。回应可说 Piacere mio / Il piacere è mio，意思是“我也很荣幸认识你”，不能把它普遍等同于 Anch’io。','Come? 单独带问号、用于没听清时，常相当于“您说什么？”；它和 Come stai? 中询问状态的用法不同。'],null,[['Piacere! — Il piacere è mio.','很高兴认识你！——我也很高兴。'],['Come? Può ripetere, per favore?','您说什么？请再说一遍好吗？']]),
section('4. 道谢和指路的称呼保持一致',['Di niente / Non c’è di che 都可回应谢谢。Figurati 对熟悉的 tu；较礼貌可以说 Si figuri。Buon viaggio! — Anche a te! 是“也祝你旅途愉快”；对尊称则可说 Anche a Lei。','笔记里的 Vai dritto / Gira a destra 对 tu；Scusi, mi può dire… 对尊称 Lei。认识这些是不同人称，不要把 vai 说成“您”的变位。'])
],[question('-issimo 构成','bello 的常用绝对高程度形式？',['bellissimo','belloissimo','il più bello 总与 bellissimo 含义相同'],0,'去末 o，加 -issimo：bellissimo。'),question('性数配合','Le case sono ___ .',['bellissima','bellissimi','bellissime'],2,'case 阴性复数，形容词最高程度词尾也用 -e。'),question('程度区别','troppo caro 表示？',['太贵；超过合适程度','只是中性的很贵','最便宜'],0,'troppo 有过度含义，不等于单纯 molto。'),question('不规则高程度','ottimo 的基本意思是？',['非常好；极佳','比较差','只能表示“最多”'],0,'ottimo 是 buono 的常见高程度形式。'),question('初次见面','Piacere! — Il piacere è mio. 这里回应的是？',['对同一食物的喜好','很高兴认识你','我也住在米兰'],1,'这是初次见面表达荣幸的接话，不是 piacere 喜好句的附和。'),question('没听清','Come? 在没听清时常表示？',['你叫什么名字','您说什么；请再说一遍','多少钱'],1,'独立的 Come? 可请求对方重复。'),question('称呼','Figurati 通常对？',['熟悉的 tu','只能对很多人','只能对尊称 Lei'],0,'tu 用 Figurati；Lei 可用 Si figuri。'),question('附和','Mi piace leggere. — 我也喜欢。',['Anche a me','Piacere mio 是本句最佳回应','Anche tu'],0,'喜欢句中的“我也”用 Anche a me。')]);

lesson(33,1,[2,3,13,27],'国籍变化与造句：从词表到完整句','补全笔记中的国籍词尾，不把身份、籍贯和位置混为一谈。',[
section('1. 国籍词像形容词一样配合',['Sono italiano/italiana；Siamo italiani/italiane。国籍词要看所指的人是单数还是复数、男性还是女性；-ese 一类单数男女同形，复数通常变 -esi。','现代常规写法里国籍、语言词通常小写，如 cinese、italiano。地名和国家名按专名大写，如 Milano、Italia、Cina。']),
section('2. 课堂国籍词全表','先看一个人，再看一群人；混合性别群体通常采用阳性复数。',table(['国籍','男性单数','女性单数','男性/混合复数','女性复数'],[['意大利','italiano','italiana','italiani','italiane'],['中国','cinese','cinese','cinesi','cinesi'],['法国','francese','francese','francesi','francesi'],['摩洛哥','marocchino','marocchina','marocchini','marocchine'],['罗马尼亚','rumeno','rumena','rumeni','rumene'],['俄罗斯','russo','russa','russi','russe'],['希腊','greco','greca','greci','greche'],['德国','tedesco','tedesca','tedeschi','tedesche']])),
section('3. 造句按“谁 + 做什么/是什么 + 补充信息”',['Io studio italiano：主语 + 动词 + 对象。Sono cinese：主语 io 已省略，用 essere 接国籍。Ho venti anni：年龄用 avere。Abito a Milano：居住地用 a + 城市。','词序并非任何情况下都只有一种，但初学先用这个最稳定的结构。否定是 Non studio italiano / Non sono cinese。名字、国籍、年龄、住处可分四个短句，比拼一个失控长句更准确。']),
section('4. 笔记中的“E…?” 是接话，不是通用变位规则',['E tu? = 你呢？E domani? = 那明天呢？E andare al cinema? = 那去看电影怎么样？最后一句把不定式动作作为话题或建议，不能推出“e 后面的动词一律必须用原形”。','当 e 连接两个完整动作，第二个动作仍需变位：Studio e lavoro（我学习并工作）。不是 Studio e lavorare。如果前面的情态动词同时支配两个不定式，则可说 Voglio studiare e lavorare。'])
],[question('国籍单数','女性说“我是意大利人”选？',['Sono italiana','Sono italiano','Ho italiana'],0,'italiana 是阴性单数。'),question('-ese','两位女性说“我们是中国人”选？',['Siamo cinese','Siamo cinesi','Siamo cinesa'],1,'cinese 的复数为 cinesi，男女相同。'),question('特殊拼写','“德国的女性们”用国籍词？',['tedesci','tedesche','tedesca'],1,'阴复数 tedesche。'),question('特殊拼写','greco 的男性复数是？',['grechi','greci','greche'],1,'男性复数 greci；阴性复数 greche。'),question('大小写','常规国籍表达选？',['Sono Cinese','Sono cinese','sono Cina'],1,'cinese 通常小写，Cina 是国家专名。'),question('句子结构','“我学习也工作”选？',['Studio e lavoro','Studio e lavorare','Studiare e lavoro'],0,'两个并列的完整动作都按 io 变位。'),question('接话','E tu? 是？',['你呢','他叫什么','我来自哪里'],0,'E + 话题可承接对方。'),question('情态支配','“我想学习和工作”选？',['Voglio studiare e lavorare','Voglio studio e lavoro','Voglio a studiare e lavoro'],0,'voglio 可共同支配两个不定式，studiare e lavorare。')]);

lesson(24,13,[5,24],'近过去时 1：avere + 过去分词','把“已经做完的一件事”讲清楚，不必局限于刚刚发生。',[
section('1. “近过去”不代表只能说刚才',['passato prossimo 常用来讲已完成的过去事件，也可以说很久以前：Due anni fa ho iniziato il corso。中文名称“近过去时”不等于必须发生在最近几分钟。','结构是“现在时的助动词 + 过去分词”。Ho mangiato 中 ho 负责表达我，mangiato 表达已经吃过。不要把两个词当成两个独立动作。']),
section('2. avere 这一套完整句子','主语改变，助动词改变；在本课普通用法中 mangiato 不随主语性数变化。',conjugation(['mangiare 的近过去时'],['ho mangiato,hai mangiato,ha mangiato,abbiamo mangiato,avete mangiato,hanno mangiato'])),
section('3. 过去分词怎么来',['规则词尾是 -are→-ato、-ere→-uto、-ire→-ito：parlato、creduto、dormito。-ere 有很多常用不规则分词，不能把规则套在 leggere、vedere、fare 上。','avere 本身的过去分词是 avuto，因此“我曾有过”是 ho avuto；essere 的过去是 sono stato/a，不是 ho essuto。'],table(['不定式','过去分词','例句'],[['leggere / scrivere','letto / scritto','Ho letto e ho scritto.'],['vedere / fare','visto / fatto','Ho visto il film.'],['dire / prendere','detto / preso','Ho preso il treno.'],['mettere / chiedere','messo / chiesto','Ho chiesto aiuto.'],['chiudere / aprire','chiuso / aperto','Ho aperto la porta.'],['offrire / vincere','offerto / vinto','Ho vinto la partita.'],['bere / avere','bevuto / avuto','Ho bevuto un caffè.']])),
section('4. 否定和时间词',['Non ho mangiato = 我没吃。Ho già mangiato = 我已经吃过。Ieri ho studiato = 昨天我学习了。第二个词保留过去分词，不写 ho mangio。','用 avere 时普通主语不决定分词词尾：两位女性说 Abbiamo mangiato。前置直接宾语代词可能引起分词配合，是另一个规则；这里先练基础形式。'])
],[question('结构','“我吃过了”选？',['Ho mangio','Ho mangiato','Sono mangiato（此义）'],1,'avere 现在时 ho + 过去分词 mangiato。'),question('助动词变位','noi + mangiare 的近过去时？',['abbiamo mangiato','hanno mangiato','siamo mangiato'],0,'noi 用 abbiamo。'),question('规则分词','dormire 的规则过去分词？',['dormato','dormuto','dormito'],2,'-ire→-ito。'),question('不规则分词','leggere 的过去分词？',['leggiuto','letto','leggato'],1,'leggere→letto，不能套规则。'),question('不规则分词','fare 的过去分词？',['fatto','faciuto','fareto'],0,'fare→fatto。'),question('avere 自身','“我有过一个问题”选？',['Ho avuto un problema','Sono avuto un problema','Ho avato un problema'],0,'avere 的分词 avuto，助动词仍是 avere。'),question('性数','两位女性说“我们吃了”选？',['Abbiamo mangiate','Abbiamo mangiato','Siamo mangiate'],1,'本课普通 avere 结构不随主语性数变化。'),question('否定','“我没喝咖啡”选？',['Ho non bevuto','Non ho bevuto un caffè','Non sono bevuto un caffè'],1,'non 放在助动词前，bere→bevuto。'),question('时间范围','passato prossimo 能说两年前完成的事吗？',['能','绝对不能','只能表达明天'],0,'它不只表示几分钟前；关键是过去完成事件的叙述。')]);

lesson(25,13,[5,23,24],'近过去时 2：essere、反身与性数配合','记常见 essere 动词，也记“移动 ≠ 一律 essere”。',[
section('1. 哪些常见动词先记 essere',['andare、venire、arrivare、partire、entrare、uscire、tornare/ritornare/rientrare，表示位置改变时常用 essere；restare、rimanere、essere、stare 也常用 essere。','nascere、morire、diventare、crescere、dimagrire、ingrassare、invecchiare、ringiovanire 在本课“自身状态变化”的不及物用法中通常用 essere。个别词换成及物义可能用 avere；不能只看中文意思判断。']),
section('2. essere 后分词要配合主语','先找主语性别和单复数，再选 -o/-a/-i/-e。混合性别群体通常用阳性复数 -i。',table(['主语','例句','含义'],[['男性单数','Sono andato a Roma.','我去了罗马（男）'],['女性单数','Sono andata a Roma.','我去了罗马（女）'],['男性/混合复数','Siamo andati a Roma.','我们去了罗马'],['全女性复数','Siamo andate a Roma.','我们去了罗马（全女）']])),
section('3. “移动用 essere”为什么不够',['viaggiare、camminare、nuotare 等表达活动，通常是 ho viaggiato / ho camminato / ho nuotato。动没动不是唯一判断标准。correre 可依句法和意义选择不同助动词，初学时不要用一条笼统口诀覆盖。','用作及物时，“我爬了楼梯”可说 Ho salito le scale；“我上到了二楼”可说 Sono salito al secondo piano。考试遇到不熟的动词，要查具体用法。']),
section('4. 反身与 essere/stare 自身的过去',['Mi sono lavato/a；Ci siamo vestiti/e。反身小代词在助动词前，分词仍按主语配合。','essere 和 stare 的分词都是 stato：sono stato/a、sei stato/a、è stato/a、siamo stati/e、siete stati/e、sono stati/e。rimanere→rimasto、venire→venuto、nascere→nato、morire→morto 都要单记。'],null,[['Ieri sono andata a scuola e ho studiato.','昨天我去了学校并学习了（女性说）。'],['Ci siamo svegliati presto.','我们很早醒来了（男/混合群体）。']])
],[question('助动词','“我去了罗马”（女性）选？',['Ho andato a Roma','Sono andata a Roma','Sono andato a Roma'],1,'andare 用 essere，女性 andata。'),question('全女性复数','两位女性说“我们出门了”选？',['Siamo uscite','Siamo usciti','Abbiamo uscita'],0,'全女性复数用 uscite。'),question('移动例外','“我旅行了很多”选？',['Sono viaggiato molto','Ho viaggiato molto','Mi sono viaggiato'],1,'viaggiare 通常用 avere，即使涉及移动。'),question('反身','“她穿好衣服了”选？',['Ha vestita','Si è vestita','Si ha vestito'],1,'反身用 essere，并按阴性 vestita。'),question('自身过去','“我曾在罗马”（男性）选？',['Ho stato a Roma','Sono stato a Roma','Sono essuto a Roma'],1,'essere 的分词是 stato，助动词也是 essere。'),question('不规则分词','venire / rimanere 的分词是？',['venito / rimanuto','venuto / rimasto','venuto / rimanito'],1,'venire→venuto，rimanere→rimasto。'),question('状态变化','“她变瘦了”选？',['È dimagrita','Ha dimagrita','È dimagrito'],0,'自身状态变化 dimagrire 用 essere，阴性 dimagrita。'),question('及物/不及物','“我爬了楼梯”可用？',['Ho salito le scale','Sono salite le scale（主语为我）','Ho saluto le scale'],0,'salire 带直接宾语 le scale 时可用 avere。')]);

lesson(26,14,[5],'一般将来时：我将去、将是、将有','补齐笔记中的三套将来时，并理解现在时也能说计划。',[
section('1. 将来时做什么',['Futuro semplice 表示相对于现在之后将发生的事：Domani andrò a Roma。与近过去时的两个词不同，它通常是一个动词词形。','日常已经安排好的计划也可说 Domani vado a Roma。两者都能成立；考试明确要求 futuro semplice 时，就使用将来时形式。']),
section('2. 课堂三套完整表','必须背准三个不同词干：andr-、sar-、avr-，再接同一套词尾。',conjugation(['andare','essere','avere'],['andrò,andrai,andrà,andremo,andrete,andranno','sarò,sarai,sarà,saremo,sarete,saranno','avrò,avrai,avrà,avremo,avrete,avranno'])),
section('3. 共同词尾与规则词（教学连接）',['六种词尾为 -ò、-ai、-à、-emo、-ete、-anno。parlare 的规则将来词干 parler-，所以 parlerò；dormire 的词干 dormir-，所以 dormirò。','不要直接写 andareò 或 essereò。不规则词干必须单记。本课重点是笔记列出的 andare/essere/avere 三组。']),
section('4. 造句时仍要检查介词和重音',['Andrò a Roma；Sarò in Italia；Avrò un esame。将来词形并不会取消原本的介词与搭配。','io 的 -ò 与 lui/lei 的 -à 要保留重音：sarò、sarà。tu 的 -ai 没有重音符号：sarai。'])
],[question('andare','“我将去”选？',['anderò','andrò','andaro'],1,'andare 的词干 andr-，我用 -ò。'),question('essere','noi + essere 将来时是？',['saremo','saranno','siamo（若题目要求将来时）'],0,'noi 为 saremo。'),question('avere','“他们将有”选？',['avrano','avranno','averanno'],1,'loro 为 avranno，双 n。'),question('人称','andrai 的主语是？',['io','tu','noi'],1,'-ai 对应 tu。'),question('重音','“她将在家”选？',['Lei sara a casa','Lei sarà a casa','Lei sarò a casa'],1,'第三人称单数 sarà，带重音 à。'),question('现在时计划','Domani vado a Roma 一定错吗？',['一定错','不一定，现在时可表达计划','只能指过去'],1,'已安排未来常用现在时；指定将来时题则用 andrò。'),question('结构','一般将来时“我将有”是？',['ho avuto','avrò','sono avuto'],1,'avrò；ho avuto 是近过去时。')]);

lesson(27,15,[26],'天气、季节、月份与节日','用 fa / c’è / è / 天气动词四类句型描述天气。',[
section('1. 天气句型不能只用一种',['Che tempo fa? 问天气。Fa caldo / Fa freddo / Fa bel tempo。C’è il sole / C’è la nebbia / C’è vento。Il cielo è sereno / nuvoloso。','下雨、下雪、打雷、冰雹可直接用第三人称单数：piove、nevica、tuona、grandina，不用 io。vento 是名词“风”，ventoso 才是“有风的”形容词。']),
section('2. 名词与形容词配对','先判断自己要说“有某物”还是“天空怎样”。',table(['名词','相关形容词/动词'],[['sole 太阳','soleggiato 阳光充足的'],['nuvola 云','nuvoloso 多云的'],['pioggia 雨','piovoso / piovere'],['neve 雪','nevicare 下雪'],['vento 风','ventoso 有风的'],['nebbia 雾','nebbioso 有雾的']])),
section('3. 四季与十二个月',['四季：primavera、estate、autunno、inverno；常用 in primavera / in estate。月份：gennaio、febbraio、marzo、aprile、maggio、giugno、luglio、agosto、settembre、ottobre、novembre、dicembre。','月份一般小写：a maggio / in maggio；日期常用 il + 基数 + 月份：il sei gennaio。月首常用 il primo maggio。']),
section('4. 笔记节日逐个认识',['Epifania 主显节 1 月 6 日；San Valentino 情人节 2 月 14 日；Festa della Donna 妇女节 3 月 8 日；Festa del Lavoro 劳动节 5 月 1 日；Natale 圣诞节 12 月 25 日；Capodanno 元旦 1 月 1 日。','Pasqua 复活节与 carnevale 狂欢节日期会变，不要背成每年某个固定日。本课只练名称与句法。星期也通常小写；lunedì=这个星期一的语境，il lunedì 常可表达“每星期一”的习惯。'])
],[question('天气句型','“天气冷”选？',['È freddo 是唯一标准天气句','Fa freddo','Ha freddo（天气主语）'],1,'基础天气表达是 fa freddo。'),question('存在','“有雾”选？',['C’è la nebbia','Fa nebbioso（本课）','Ho nebbia'],0,'nebbia 是名词，用 c’è。'),question('词类','vento 与 ventoso 分别是？',['名词风/形容词有风的','形容词/名词','都是动词'],0,'不要把 vento 直接解释为形容词“有风的”。'),question('动词','“下雪了/下雪”现在时选？',['Nevica','Nevico（无人称天气）','È nevicare'],0,'天气动词通常用第三人称单数。'),question('季节','inverno 是？',['春','秋','冬'],2,'inverno=冬天。'),question('月份','luglio 是？',['六月','七月','八月'],1,'giugno 六月、luglio 七月、agosto 八月。'),question('日期','“五月一日”选？',['il primo maggio','il uno maggio 是本课默认','la prima maggio'],0,'月首日期常用 il primo。'),question('节日','哪个日期不是每年固定同一天？',['Natale','Epifania','Pasqua'],2,'复活节为变动日期，课中不硬编码。')]);

lesson(28,16,[27],'直接宾语代词：它、他们与我、你','先判断“动作直接作用于谁/什么”，再替换。',[
section('1. 为什么叫“直接宾语”',['Mangio la pizza：我吃什么？披萨。la pizza 就是动作直接作用的对象。为了不重复，可以说 La mangio。这里 la 不再是名词前冠词，而是“它”的宾语代词。','直接宾语回答“谁/什么”，通常不通过 a 连接；Mi piace 的 mi 则是“对我”，属于间接宾语。不要因为同样拼作 mi 就混淆功能。']),
section('2. 全表','第三人称要跟被替代对象的性别和数量配合。',table(['所指对象','代词','例句'],[['我','mi','Mi vedi? 你看见我吗？'],['你','ti','Ti vedo. 我看见你。'],['他/它（阳单）','lo','Il libro? Lo leggo.'],['她/它（阴单）','la','La pizza? La mangio.'],['我们','ci','Ci vedi? 你看见我们吗？'],['你们','vi','Vi vedo. 我看见你们。'],['他们/它们（阳复）','li','I libri? Li leggo.'],['她们/它们（阴复）','le','Le lettere? Le leggo.']])),
section('3. 位置：放在变位动词前',['La compro。Non la compro。否定 non 在代词+动词之前。不要写 Compro la 来代替“我买它”；那更像缺了名词的冠词。','有情态动词时可接不定式末尾：Voglio comprarla；也可说 La voglio comprare。此处掌握两种位置即可，别同时写两次 la。']),
section('4. 和过去时衔接（拓展提醒）',['Ho letto la lettera → L’ho letta。直接宾语 lo/la/li/le 放到 avere 过去时前时，过去分词通常要跟它配合。','这条不同于“avere 一般不跟主语配合”：配合的是前置直接宾语，而不是说话者。基础考试先把现在时代词替换练熟。'])
],[question('阴单','La pizza? ___ mangio.',['Lo','La','Le'],1,'pizza 阴性单数，代词 la。'),question('阳复','I libri? ___ leggo.',['Li','Le','Lo'],0,'libri 阳性复数，用 li。'),question('阴复','Le lettere? ___ scrivo.',['Li','La','Le'],2,'lettere 阴性复数，用 le。'),question('人称','“我看见你”选？',['Mi vedo','Ti vedo','Lo vedo'],1,'ti = 你（宾语）。'),question('位置','“我不买它”（la macchina）选？',['Non la compro','La non compro','Non compro la'],0,'non + 代词 + 变位动词。'),question('情态','“我想买它”（la macchina）选？',['Voglio comprarla','Voglio la comprare（此语序）','La voglio comprarla'],0,'可把 la 接在不定式后：comprare 去末 e + la。'),question('辨 mi','Mi piace la pizza 中 mi 是直接宾语吗？',['是','不是，是间接宾语','是主语'],1,'表示“对我”，pizza 才是主语。'),question('过去拓展','La lettera? L’ho ___ .',['letto','letta','leggo'],1,'前置 la 对应阴单分词 letta。')]);

lesson(29,16,[13,27],'家庭成员：说清关系和所有格','认清 parente、genitore、nipote 这几个容易按英语猜错的词。',[
section('1. 关系词按家庭树记',['nonno/nonna=祖父母辈；padre/madre=父母；marito/moglie=丈夫/妻子；figlio/figlia=儿子/女儿；fratello/sorella=兄弟/姐妹；zio/zia=叔舅姑姨辈；cugino/cugina=堂表兄弟姐妹。','genitori 才是“父母”；parenti 是“亲戚”，不是英语 parents。nipote 可指孙辈或侄甥辈，要靠上下文；cognato 是男性姻亲同辈，如姐夫、妹夫等，并非固定一种中国亲属关系。']),
section('2. 物主与家庭称谓再练一次',['Sono figlia unica = 我是独生女。Ho una sorella = 我有一个姐妹。Lei è mia sorella = 她是我的姐妹。表达“拥有”和“身份”用不同的句子。','mio padre、mia madre、mio fratello；复数 i miei fratelli。il loro padre 保留冠词。说全家是 la mia famiglia，famiglia 不是“某一位单数亲属称谓”，不套省冠词规则。']),
section('3. 描述一个家人','先说关系，再说名字、年龄、职业、住处或喜好。把已学的句型串起来。',null,[['Mia sorella si chiama Anna. Ha venti anni e studia a Roma.','我的姐妹叫 Anna，二十岁，在罗马学习。'],['Mio padre è medico. Gli piace leggere.','我的爸爸是医生。他喜欢读书。']])
],[question('易混词','parenti 是？',['父母','亲戚','儿女'],1,'父母是 genitori；parenti 是亲戚。'),question('易混词','genitori 是？',['祖父母','父母','同学'],1,'genitore 单数指父或母，复数 genitori 指父母。'),question('多义','nipote 可能指？',['只可能祖父','孙辈或侄甥辈','只可能丈夫'],1,'需用上下文判断具体亲属关系。'),question('家庭物主','“我的家庭”选？',['mia famiglia（本课默认）','la mia famiglia','il mio famiglia'],1,'famiglia 不适用单数亲属称谓省冠词规则。'),question('独生女','“我是独生女”选？',['Sono figlia unica','Ho figlia unica','Sono unico figlia'],0,'figlia 阴性，形容词 unica。'),question('关系身份','“她是我妹妹/姐姐”选？',['Lei ha mia sorella','Lei è mia sorella','Lei è la mia famiglia 语义相同'],1,'用 essere 说明她的身份关系。')]);

lesson(30,16,[27,28],'自我介绍到写信：把句子接成一段','来源、居住、回信目的、时间表达一起用。',[
section('1. 来自哪里，与住在哪里',['Vengo da Shanghai / Sono di Shanghai=来自上海；Sono cinese=中国人；Abito/Studio/Vivo a Milano=住/学/生活在米兰。它们不是同一种信息。','写一段自我介绍，可以按名字→国籍/来源→年龄→现在居住→学习/爱好这个顺序。不要把 di、da、a 当成可随意替换的“在”。']),
section('2. 笔记里的书信开头','先完整理解每个句块，再按真实内容替换。',null,[['Ciao! Come stai? Sto bene. E tu?','你好！你好吗？我很好。你呢？'],['Sono molto felice di ricevere la tua lettera.','我很高兴收到你的信。'],['Ti scrivo per risponderti e per raccontarti qualcosa.','我写信来回复你，并给你讲一些事情。'],['Per quanto riguarda la tua domanda, ti dico che sto bene.','关于你的问题，我告诉你我很好。']] ),
section('3. 看懂长词里的代词',['risponderti = rispondere + ti（回复你）；raccontarti = raccontare + ti（向你讲述）。接在不定式后时，原形末尾 e 去掉。','Ti scrivo per… 中 per + 不定式表示目的。Sono felice di… 中 di 是 felice 这一表达的搭配。不要把所有第二个动作都加 a。']),
section('4. 时间与范围句块',['a partire da=从……起；tutti i giorni=每天；qualche volta=有时候；dalle 10 alle 19:30=从十点到十九点半；tutto il mondo=全世界；due anni fa=两年前。','最后写 5–7 句真实介绍，并按清单检查：人称变位、国籍性别、城市介词、冠词、年龄 avere、否定位置。答案题可由选择题检查规则；自由写作需要自己结合这些检查点改写。'])
],[question('来源','“我来自上海”可说？',['Sono di Shanghai','Sono a Shanghai 语义相同','Ho Shanghai'],0,'di 表出身；a 表所在。'),question('居住','“我住在米兰”选？',['Abito di Milano','Abito a Milano','Abito da Milano'],1,'城市前通常 a。'),question('搭配','Sono felice ___ ricevere la tua lettera.',['a','di','perché'],1,'felice di + 不定式。'),question('目的','Ti scrivo ___ risponderti.',['per','a（本句）','che'],0,'per + 不定式表示目的。'),question('词内代词','risponderti =？',['回复我','回复你','他们回复'],1,'ti 为“你”的代词，接不定式后。'),question('时间','a partire da domani 意思？',['昨天之前','从明天起','明天已经过去'],1,'a partire da 表起点。'),question('范围','tutto il mondo 是？',['全世界','每个周末','两年前'],0,'mondo=世界，tutto il=整个……。'),question('拼句','“我二十岁，住在米兰”选？',['Sono venti anni e vivo di Milano','Ho venti anni e vivo a Milano','Ho venti anno e vivo in Milano'],1,'年龄 avere + anni；城市 a。')]);

lesson(31,17,[15,25,29],'阅读扩展：连接词、近义词和固定表达','把笔记最后几页词汇真正用于读句子。',[
section('1. 转折词的力度与位置',['ma 是常用“但是”；però 更有口语弹性；tuttavia 较书面；eppure 表“尽管这样却仍”；invece 常作对比“而/相反”。它们有关联，但不是随处能替换。','Io studio, lui invece lavora：对比两个人。È stanco, eppure continua a lavorare：强调虽累却还工作。infatti 用来解释/印证，不是“但是”。']),
section('2. 动词要连搭配学',['avere bisogno di + 名词/不定式：Ho bisogno di aiuto / di studiare。avere fretta=赶时间。frequentare un corso / il liceo=上课/上高中。conoscere 一个人或地方，sapere 一个事实或技能。','esibire un documento=出示证件；“登台表演”通常是 esibirsi。dirigere 可说领导/指挥；raccogliere 可说收集/采摘；同词多义要看宾语。']),
section('3. 不要按相似拼写猜义',['attualmente=目前，不等于英语 actually（实际上）。estero=国外/外国的，不是 esercito（军队）；旧版误录成 esercito，已改正。coinquilino 是合租室友，vicino 可指邻居或“近的”，两者也不同。','maggiore=更大/年长/更重要；migliore=更好；peggio=更糟（副词），不能把这些比较意思全部译成“最大”。soddisfatto=满意，不是 rilassato=放松。']),
section('4. 用上下文理解过去分词',['rimasto 是 rimanere 的过去分词；saltato 是 saltare 的过去分词。看到词尾 -ato 并不总是一个独立的形容词：Ho saltato la colazione=我没吃早餐。','新词卡的例句为学习编写，词本身来自标注的课堂页码。读句时先划出动词，再看主语、宾语和连接词，会比逐词翻译更清楚。'])
],[question('连接词','“我学习，而他工作”最适合选？',['Io studio, lui invece lavora','Io studio, lui infatti è me','Io studio, lui non c’è'],0,'invece 对比两种情况。'),question('搭配','Ho bisogno ___ aiuto.',['a','di','con'],1,'avere bisogno di 是固定结构。'),question('易混义','attualmente 是？',['实际上（actually）','目前','最终'],1,'attualmente=目前/现在。'),question('误录修正','“国外/外国的”应选？',['estero','esercito','esame'],0,'estero=国外/外国的；esercito=军队。'),question('动词辨义','“出示证件”选？',['esibire un documento','esibirsi un documento','essere un documento'],0,'esibire 为及物“展示/出示”；esibirsi 为表演。'),question('人物辨义','coinquilino 是？',['合租室友','仅指邻居','售货员'],0,'vicino 可指邻居，coinquilino 是合住的人。'),question('近义辨析','soddisfatto 是？',['满意的','困倦的','紧急的'],0,'满意=soddisfatto；困倦=assonnato。'),question('过去分词','Ho saltato la colazione 意思？',['我跳进早餐','我没吃早餐','我正在买早餐'],1,'saltare 在这里意为跳过、没做。')]);

lesson(18,9,[17,18],'问路、交通与方位：跟着箭头走','先掌握能求助的完整问句，再听懂方向词。',[
section('1. 用什么句子问路',['Scusi, mi può dire dov’è la stazione? 劳驾，您能告诉我车站在哪里吗？Mi sono perso（男性）/ persa（女性）表示我迷路了。','Come arrivare a…? 可作“如何到……”的问句/标题；更完整地问别人可说 Come posso arrivare alla stazione? 注意 a + la 缩合为 alla。']),
section('2. 最常见的指路块','把方向词作为整块来听，先别急着拆每个词。',table(['句块','意思'],[['Vai dritto.','直走（对 tu）'],['Gira a destra / a sinistra.','右转 / 左转'],['Fino al semaforo.','直到红绿灯'],['Alla prima traversa.','在第一条横街处'],['All’incrocio.','在交叉口'],['È dietro l’angolo.','就在拐角处'],['In direzione del centro.','朝市中心方向']])),
section('3. 交通工具前的介词',['andare in treno / in autobus / in bici / in metro / in aereo，表示乘坐方式。prendere 是“乘/搭”，后接冠词+名词：prendere il treno / l’autobus / l’aereo。步行固定说 a piedi。','Salgo sul treno=上火车；Scendo dal treno=下火车。Scendo alla prossima fermata=在下一站下车。binario 是铁路股道/站台编号，fermata 是停靠站点，两者别混。']),
section('4. 方位先确定参照物',['sopra/sotto=上方/下方；dentro=里面；dietro=后面。vicino a / accanto a / davanti a / di fronte a 常用 a 连接参照物。','La banca è di fronte alla scuola = 银行在学校对面。a 遇 la 要缩合成 alla。不要把英语 in front of 的词序直接搬过来。'],null,[['Il bar è accanto alla stazione.','酒吧紧挨着车站。'],['La borsa è sotto il tavolo.','包在桌子下面。']])
],[question('问路','“劳驾，您能告诉我车站在哪吗？”选？',['Mi può dire dov’è la stazione?','Mi posso dire la stazione?','Mi puoi dire? 是对 Lei 的尊称'],0,'può 是尊称 Lei 的变位。'),question('方向','“直走”选？',['Vai dietro','Vai dritto','Vai dentro'],1,'dritto 表直行。'),question('方向','a sinistra 的意思？',['向右','向左','直走'],1,'sinistra 左，destra 右。'),question('交通','“我乘火车去”选？',['Vado in treno','Vado a treno','Vado il treno'],0,'表达乘坐方式用 in treno。'),question('prendere','“我坐公交”选？',['Prendo in autobus','Prendo l’autobus','Prendo a autobus'],1,'prendere 后直接接带冠词的交通工具。'),question('下车','“从火车下车”选？',['Scendo dal treno','Scendo sul treno','Scendo nel treno'],0,'da + il = dal，表示从车上下来。'),question('方位','“在学校对面”选？',['di fronte della scuola','di fronte alla scuola','di fronte la scuola'],1,'di fronte a + la = di fronte alla。'),question('位置','sotto il letto 是？',['在床上','在床下','在床后面'],1,'sotto = 在下面。')]);

lesson(19,10,[20],'数字与序数：数量、钱和第几','先会 0–20，再组合几十和序数。',[
section('1. 基数词表示数量',['0–10：zero, uno, due, tre, quattro, cinque, sei, sette, otto, nove, dieci。11–20：undici, dodici, tredici, quattordici, quindici, sedici, diciassette, diciotto, diciannove, venti。','几十是 trenta、quaranta、cinquanta、sessanta、settanta、ottanta、novanta；100 cento、200 duecento、1000 mille。词库里每个笔记数字都可以朗读和听写。']),
section('2. 组合时的拼写',['venti + uno → ventuno；venti + otto → ventotto，十位末元音遇 uno/otto 常省略。23 是 ventitré，最后的 tré 带重音。101 用 centouno（也见 centuno）；本课采用 centouno。','数字前不要套中文“个”的量词：due libri、tre persone。年龄仍是 Ho + 数字 + anni；价格可说 Costa venti euro，euro 通常单复数同形。']),
section('3. 序数词表示位置','前十个单独背：primo、secondo、terzo、quarto、quinto、sesto、settimo、ottavo、nono、decimo。序数像 -o 形容词一样变：la prima volta、i primi giorni。',table(['数字','序数','说明'],[['11 / 12','undicesimo / dodicesimo','词干 + -esimo'],['20','ventesimo','venti 去末 i'],['23','ventitreesimo','保留 tre 的 e，不保留重音符号'],['36','trentaseiesimo','保留 sei'],['100 / 101','centesimo / centounesimo','百/一百零一'],['1000','millesimo','第一千']])),
section('4. 基数与序数不要混',['due libri=两本书；il secondo libro=第二本书。铁路站台编号通常 binario due，不必处处使用序数。日期月首常用 il primo，其他日子用基数。'])
],[question('组合','21 的拼写是？',['ventiuno','ventuno','ventuno’'],1,'venti + uno 省末 i。'),question('重音','23 的拼写是？',['ventitre','ventitré','ventitrè 是本课标准'],1,'ventitré 的词尾 é 带尖重音。'),question('组合','28 的拼写是？',['ventiotto','ventotto','ventottoe'],1,'venti + otto → ventotto。'),question('序数','“第二本书”选？',['due libro','il secondo libro','il due libro'],1,'第二用 secondo，跟 libro 阳单配合。'),question('序数配合','“第一次”选？',['la prima volta','la primo volta','il prima volta'],0,'volta 阴性，序数用 prima。'),question('特殊序数','第 23 的规范拼写？',['ventitresimo','ventitreesimo','ventitrésimo'],1,'保留 tre 的 e，接 -esimo 成 -treesimo。'),question('特殊序数','第 36 选？',['trentaseiesimo','trentasesimo','trentasettesimo'],0,'sei 部分保留，trentaseiesimo。'),question('百千','1000 是？',['cento','mille','duecento'],1,'mille 是一千。')]);

lesson(20,10,[19,28],'几点、几点做事、从几点到几点','把钟点本身和时间状语分开。',[
section('1. 说“现在几点”',['Che ora è? / Che ore sono? 都可问几点。回答一点用 È l’una。大多数其他钟点用 Sono le + 数字：Sono le due。中午和午夜是 È mezzogiorno / È mezzanotte。','Sono le otto 描述钟点；Alle otto 表示某事发生的时间。不要把回答“几点了”直接说成 Alle otto。']),
section('2. 分钟怎么表达','e = 加上分钟，meno = 距下一钟点还差几分钟。',table(['钟面','表达','理解'],[['2:05','Sono le due e cinque.','两点零五'],['2:15','Sono le due e un quarto.','两点一刻'],['2:30','Sono le due e mezzo.','两点半'],['2:45','Sono le tre meno un quarto.','差一刻三点'],['2:55','Sono le tre meno cinque.','差五分三点']])),
section('3. 加入日程和区间',['Vado a lezione alle otto。a+le→alle；一点是 all’una，中午 a mezzogiorno，午夜 a mezzanotte。','Dalle dieci alle diciannove e trenta 表示从十点到十九点半。dalle/alle 不是可拆开乱放的单独单词，要让“从……到……”成对出现。']),
section('4. 时段与多久以前',['del mattino / del pomeriggio / di sera / di notte 可帮助说明时段。alle otto di sera=晚上八点。','due anni fa=两年前；tra due anni=两年后；a partire da domani=从明天起。fa 放在时长后，tra/fra 放在时长前。'])
],[question('钟点','“现在一点”选？',['Sono le una','È l’una','È la uno'],1,'一点用 È l’una。'),question('钟点','“现在八点”选？',['Sono le otto','Alle otto','È otto'],0,'描述钟点用 Sono le otto。'),question('时间状语','“我八点学习”选？',['Studio le otto','Studio alle otto','Studio sono le otto'],1,'几点做事用 alle + 钟点。'),question('一刻','2:15 选？',['le due e un quarto','le due meno un quarto','le tre e mezzo'],0,'e un quarto = 过十五分钟。'),question('差一刻','2:45 选？',['le due meno un quarto','le tre meno un quarto','le tre e un quarto'],1,'差一刻三点。'),question('区间','“从十点到十二点”选？',['dalle dieci alle dodici','alle dieci dalle dodici','da dieci a le dodici'],0,'dalle…alle… 是完整区间。'),question('过去时间','“两年前”选？',['fa due anni','due anni fa','tra due anni'],1,'fa 放在时长后。'),question('特殊时刻','“在中午”选？',['alle mezzogiorno','a mezzogiorno','all’mezzogiorno'],1,'中午用 a mezzogiorno。')]);

lesson(21,11,[19,21],'酒店与家居：预订、设施、故障','把词库里的名词放进实际会用到的句子。',[
section('1. 预订时要说明什么',['Vorrei prenotare una camera singola / doppia / matrimoniale。singola 是单人间；doppia 指双人入住，床型需要进一步确认；matrimoniale 通常为一张双人大床。','问价格：Quanto costa una notte? / Quanto viene in tutto? 问是否包含：La colazione è inclusa/compresa? colazione 阴性，所以是 inclusa/compresa。']),
section('2. 描述房间位置和物品',['C’è un letto、Ci sono due sedie。La camera è luminosa、Il bagno è piccolo。用上一单元方位：La valigia è sotto il letto。','家居词包括房间、家具、厨房器具、洗衣机/洗碗机等。lavatrice=洗衣机；lavastoviglie=洗碗机，笔记中相近拼写容易混，网站已统一。']),
section('3. 报告故障四种句型','逐条换入你遇到的设施。',table(['问题','句型','例子'],[['没有某物','Non c’è / Non ci sono','Non c’è la carta igienica.'],['缺少某物','Manca / Mancano','Mancano gli asciugamani.'],['不能运作','Non funziona / Non funzionano','L’ascensore non funziona.'],['坏掉/破损','È rotto/a / Sono rotti/e','La lampada è rotta.']])),
section('4. 服务相关词的准确含义',['annullare=取消，prenotare/riservare=预订，pernottare=住宿过夜，coperto 可指有遮蔽的，也可在餐馆指餐位费。venire 在 Quanto viene? 里相当于“算下来多少钱”。','“坏了”是 rotto/rotta，旧版 hotto 是误拼，已删除。要让形容词和名词配合：il telefono è rotto / la lampada è rotta。'])
],[question('房型','一张双人大床通常选？',['camera singola','camera matrimoniale','bagno'],1,'matrimoniale 通常表示大床房。'),question('包含','La colazione è ___ .',['incluso','inclusa','inclusi'],1,'colazione 阴单，用 inclusa。'),question('故障','“灯坏了”选？',['La lampada è rotto','La lampada è rotta','La lampada è hotto'],1,'rotto 正确拼写，按阴性变 rotta。'),question('缺少','“缺毛巾（多条）”选？',['Mancano gli asciugamani','Manca gli asciugamani','Manco asciugamani'],0,'复数 asciugamani 用 mancano。'),question('设施','lavastoviglie 是？',['洗衣机','洗碗机','吹风机'],1,'洗衣机是 lavatrice。'),question('运作','“空调不工作”选？',['L’aria condizionata non funziona','L’aria condizionata non funzionano','L’aria non è funziona'],0,'aria condizionata 单数，用 non funziona。'),question('取消','“我想取消预订”选？',['Vorrei annullare la prenotazione','Vorrei includere la prenotazione','Vorrei perdere la prenotazione'],0,'annullare = 取消。')]);

lesson(22,12,[22,28],'爱好与频率：我经常、从不做什么','先选正确的爱好搭配，再放频率副词。',[
section('1. 玩球和演奏不同动词',['giocare a calcio / a pallavolo / a pallacanestro，球类运动常用 giocare a；演奏乐器用 suonare：suonare la chitarra。','fare sport / fare ginnastica，散步 passeggiare，去电影馆 andare al cinema。“玩吉他”不能照中文写 giocare la chitarra。']),
section('2. 频率从高到低','频率副词表示大概习惯，并不是严格百分比。',table(['词','中文','例句'],[['sempre / quasi sempre','总是 / 几乎总是','Studio sempre a casa.'],['spesso','经常','Vado spesso al cinema.'],['di solito / generalmente','通常','Di solito studio la sera.'],['ogni tanto / a volte / qualche volta','有时','A volte esco.'],['raramente','很少','Esco raramente.'],['mai / quasi mai','从不 / 几乎从不','Non esco mai.']])),
section('3. non…mai 的位置',['最基础的“从不”是 Non + 动词 + mai：Non mangio mai carne。mai 在动词前时可有特殊句式，但初学者先把这个结构练稳。','sempre 常置变位动词后：Mangio sempre la pizza。spesso、di solito、a volte 的位置更灵活；本课使用最清楚的句首或动词后位置。']),
section('4. 每天与有时',['tutti i giorni=每天；ogni giorno 的 giorno 用单数。qualche volta 的 volta 用单数，即使中文表示不止一次，也不能写 qualche volte。'])
],[question('球类','“踢足球”选？',['suonare calcio','giocare a calcio','giocare il calcio'],1,'球类常用 giocare a。'),question('乐器','“弹吉他”选？',['suonare la chitarra','giocare la chitarra','fare a chitarra'],0,'乐器用 suonare。'),question('频率','spesso 表示？',['从不','经常','偶尔'],1,'spesso = 经常。'),question('从不','“我从不吃肉”选？',['Mangio mai carne','Non mangio mai carne','Non mai mangio carne 是本课基础语序'],1,'基础结构是 non + 动词 + mai。'),question('总是','“我总在家学习”选？',['Studio sempre a casa','Sempre non studio a casa','Studio mai a casa'],0,'sempre 常在变位动词后。'),question('单数','“有时”选？',['qualche volte','qualche volta','qualchi volta'],1,'qualche 后用单数名词 volta。'),question('每天','“每天”可说？',['ogni giorni','tutti i giorni','tutti il giorno'],1,'tutti i giorni；或 ogni giorno。')]);

lesson(23,12,[23],'反身动词：我洗漱、你起床、我们穿衣','代词与动词都需要跟主语一起变。',[
section('1. 为什么多了 mi / ti / si',['lavare 是洗某物：Lavo i piatti。lavarsi 是洗自己：Mi lavo。词典里的 -si 提示这是反身/代词式动词。变位时去掉 -si，恢复 -re，再按人称同时处理小代词和动词。','mi、ti、si、ci、vi、si 分别对应我、你、他她、我们、你们、他们她们。不是每个出现 mi 的句子都是反身句：Mi piace 中 mi 是间接宾语。']),
section('2. 三组完整形式','sedersi 的重读形式有 sied-，noi/voi 为 sed-；vestirsi 的 lui/lei 是 si veste，不能误写成 si vesto。',conjugation(['lavarsi','sedersi','vestirsi'],['mi lavo,ti lavi,si lava,ci laviamo,vi lavate,si lavano','mi siedo,ti siedi,si siede,ci sediamo,vi sedete,si siedono','mi vesto,ti vesti,si veste,ci vestiamo,vi vestite,si vestono'])),
section('3. 用一段日常练习',['Mi sveglio=醒来，Mi alzo=起床，Mi lavo=洗漱，Mi vesto=穿衣，Mi addormento=睡着。这些动作的顺序有助于记忆。','否定仍放前面：Non mi alzo presto。用情态时可说 Voglio alzarmi / Mi voglio alzare；初学先用 alzarmi 这种把 mi 接在不定式后的形式。'],null,[['Mi sveglio alle sette e poi mi alzo.','我七点醒来，然后起床。'],['Ci vestiamo e facciamo colazione.','我们穿好衣服，然后吃早餐。']]),
section('4. 与过去时连接','反身动词的近过去时通常用 essere：Mi sono lavato（男性）/ Mi sono lavata（女性）。不要写成 mi ho lavato。过去分词性数配合会在过去时单元细讲。')
],[question('代词','“我们洗漱”选？',['si laviamo','ci laviamo','mi laviamo'],1,'noi 的代词 ci，动词 laviamo。'),question('完整变位','“她穿衣服”选？',['si vesto','si veste','ti veste'],1,'lei 为 si veste。'),question('不规则','“我坐下”选？',['mi sedo（本课标准）','mi siedo','si siedo'],1,'本课采用常用 mi siedo。'),question('noi','“我们坐下”选？',['ci siediamo','ci sediamo','si sediamo'],1,'noi 为 ci sediamo，不加 ie。'),question('顺序','svegliarsi 与 alzarsi 分别是？',['起床/入睡','醒来/起床','洗漱/穿衣'],1,'醒来并不等于已经起床。'),question('否定','“我不早起”选？',['Mi non alzo presto','Non mi alzo presto','Non alzo mi presto'],1,'non 放在代词+动词前。'),question('辨义','Lavo i piatti 是？',['我洗自己','我洗盘子','我穿衣服'],1,'lavare + 宾语是洗某物；lavarsi 是洗自己。'),question('过去','女性说“我洗漱了”选？',['Mi ho lavato','Mi sono lavata','Mi sono lavato'],1,'反身过去用 essere，女性分词 lavata。')]);

lesson(9,4,[7,9,15],'形容词与颜色：词尾跟着谁变','描述房间、人物和物品时，性别与数量要一起配合。',[
section('1. 形容词跟被描述的名词配合',['la casa bella、il libro bello：词尾跟“房子/书”的语法性别配合，不跟说话人配合。用 essere 连接也一样：La casa è bella。','以 -o 结尾的形容词通常有四种：bello/bella/belli/belle。以 -e 结尾的通常单数 -e、复数 -i：interessante/interessanti。']),
section('2. 把一组词尾看全','不要只背“漂亮=bell-”，要能根据名词选形。',table(['词类','阳单','阴单','阳复','阴复'],[['-o 形容词','nuovo','nuova','nuovi','nuove'],['-e 形容词','grande','grande','grandi','grandi'],['-e 颜色词','verde','verde','verdi','verdi'],['不变颜色（本课常用）','blu','blu','blu','blu']])),
section('3. 颜色分组',['rosso/azzurro/nero/giallo/bianco/grigio 按 -o 一组变化；verde/marrone/arancione 在本课采用 verdi/marroni/arancioni 的规范配合。部分颜色在真实用法中也有不变形式，考试先用课堂这一组。','blu、rosa、viola、beige 通常保持不变：le maglie rosa、i pantaloni blu。不要写成 blu 的人为复数 blui。']),
section('4. 同义近义不等于随便互换',['buono 多说品质、味道好；bene 是副词或状态词：La pasta è buona，但 Sto bene。comodo/scomodo 描述舒适或便利；silenzioso/rumoroso 描述安静或嘈杂。','常见形容词可放名词后；放在名词前有时会改变语气或意思。初学者先用“名词 + 常规形容词”与“名词 + essere + 形容词”。'])
],[question('四形','la casa ___',['nuovo','nuova','nuovi'],1,'casa 阴性单数，所以 nuova。'),question('四形','i libri ___',['belli','belle','bella'],0,'libri 阳性复数，用 belli。'),question('两形','le lezioni ___',['interessante','interessanti','interessanta'],1,'interessante 复数为 interessanti，男女相同。'),question('颜色','le scarpe ___（绿色）',['verdi','verde','verda'],0,'verde 复数为 verdi。'),question('不变颜色','i pantaloni ___（蓝色）',['blui','blu','bluo'],1,'blu 通常不变。'),question('不变颜色','le maglie ___（粉色）',['rose','rosa','rosi'],1,'颜色用法 rosa 通常不变；rose 作为名词则是玫瑰花复数。'),question('词类','“我很好”选？',['Sto buono','Sto bene','Sono bene'],1,'常用状态表达是 Sto bene。')]);

lesson(10,5,[9,11],'简单介词：地点、来源、目的','介词不是一对一翻译，要跟搭配一起记。',[
section('1. 先区分“来源”和“所在”',['Vengo da Milano：我从米兰来。Sono di Milano：我的籍贯/出身在米兰。Sono a Milano：我现在在米兰。三个句子含义不一样。','城市通常 a，国家/区域通常 in：a Roma / in Italia。对具体地点，不要只背“a=小地方、in=大地方”，应记具体搭配。']),
section('2. a / in 的课堂搭配','把同类连读，积累语感。',table(['a 一组','in 一组'],[['a casa / a scuola / a letto','in banca / in ufficio / in biblioteca'],['a teatro / a lezione / a messa','in palestra / in piscina / in discoteca'],['a Roma / a Milano','in Italia / in città / in centro'],['a piedi / a pranzo / a cena','in treno / in bici / in metro']])),
section('3. 其余介词各做什么','di 表所属/来源/主题；da 可表从、在某人处；su 表在上面或关于；con 表和、用；per 表目的/给/经过；tra/fra 表之间或“再过……”。',null,[['Il libro di Maria è sul tavolo.','Maria 的书在桌子上。'],['Esco con gli amici e studio per l’esame.','我和朋友们出门，并为考试学习。'],['Parto tra due giorni.','我两天后出发。']]),
section('4. 带冠词与不带冠词并不矛盾',['Vado in biblioteca 是常用地点搭配；Vado nella biblioteca nuova 指具体的那家新图书馆。Abito in una casa grande 里带不定冠词，但仍用 in。','如果后面有定冠词 a/in/di/da/su，往往要缩合。下一课会给完整表。不要把“in 固定搭配不带冠词”理解为永远不能带冠词。'])
],[question('国家','Vivo ___ Italia.',['a','in','di'],1,'国家前常用 in。'),question('城市','Vado ___ Roma.',['in','a','da'],1,'城市前常用 a 表目的地。'),question('来源','Vengo ___ Milano.',['da','a','su'],0,'venire da 表从哪里来。'),question('籍贯','Sono ___ Shanghai.（来自）',['a','in','di'],2,'essere di 表籍贯。'),question('搭配','“去图书馆”选？',['Vado a biblioteca','Vado in biblioteca','Vado di biblioteca'],1,'常用 in biblioteca。'),question('时间','“两天后”选？',['tra due giorni','due giorni fa','di due giorni'],0,'tra/fra + 时段表示从现在往后。'),question('目的','Studio ___ l’esame.',['con','per','su'],1,'per l’esame = 为考试。'),question('具体地点','in + la biblioteca nuova =？',['in la biblioteca nuova','nella biblioteca nuova','alla biblioteca nuova 是 in 的缩合'],1,'in + la = nella。')]);

lesson(11,5,[13],'缩合介词：把 a + il 变成 al','完整表格其实是五行同一种操作。',[
section('1. 为什么会缩合',['先选介词，再选冠词，最后合写。比如“去那家酒吧”：a + il bar → al bar。不是先随机背出 al 再猜意思。','只有后面实际需要定冠词时才缩合。a Roma 不需要冠词，因此不能凭空变成 al Roma。per/tra/fra 不与冠词合写；con + il 可写 col，但本课先用 con il。']),
section('2. 五种介词的完整表','纵向看冠词位置不变，横向看同一介词遇到不同冠词怎么写。',table(['介词','il','lo','l’','la','i','gli','le'],[['a','al','allo','all’','alla','ai','agli','alle'],['da','dal','dallo','dall’','dalla','dai','dagli','dalle'],['di','del','dello','dell’','della','dei','degli','delle'],['in','nel','nello','nell’','nella','nei','negli','nelle'],['su','sul','sullo','sull’','sulla','sui','sugli','sulle']])),
section('3. 按四步拆解',['例一：在桌上 → su + il tavolo → sul tavolo。例二：给那些朋友 → a + gli amici → agli amici。例三：从学校 → da + la scuola → dalla scuola。','l’ 的撇号与下词紧贴：all’università，不能在撇号后加空格。alla stazione 的 stazione 为阴性，不因为 st 开头改成 allo。'])
],[question('a 缩合','a + il =？',['al','del','nel'],0,'a + il = al。'),question('in 缩合','in + gli =？',['nelli','negli','nelle'],1,'in + gli = negli。'),question('di 缩合','di + la =？',['dalla','della','della la'],1,'di + la = della；dalla 是 da + la。'),question('su 缩合','su + il tavolo =？',['sul tavolo','su il tavolo','sullo tavolo'],0,'su + il = sul。'),question('阴性','a + la stazione =？',['allo stazione','alla stazione','al stazione'],1,'先看阴性 la，再缩合成 alla。'),question('元音','a + l’università =？',['all’università','alla università','al’università'],0,'a + l’ = all’。'),question('不缩合','per + il museo =？',['pelmuseum','per il museo','al museo'],1,'本课使用 per il，不合写。')]);

lesson(12,6,[10,12],'点单与数量：把礼貌和份量说清楚','用五种点单句式应对咖啡馆，再学程度词。',[
section('1. 五种点单方式','Prendo… 是“我要/我点……”；Vorrei… 更委婉；Posso avere…? 是“我可以要……吗”。Vorrei 是 volere 的条件式常用形式，此处先当礼貌句块记，不把它当现在时变位。',table(['表达','例句'],[['直接点单','Prendo un caffè.'],['说明我要什么','Per me, un caffè.'],['委婉请求','Vorrei un caffè, per favore.'],['询问可否提供','Posso avere un caffè?'],['最短礼貌句','Un caffè, per favore.']])),
section('2. 从“一杯”到“一些”',['un caffè、una tazza di tè、un bicchiere d’acqua、una bottiglia di vino。量词后常用 di；元音前常写 d’acqua。','食物分不分复数影响句子：un panino；due panini。gli spaghetti 是复数；la pasta 多用单数。不要把中文“一份”强行等于每个食物名词的单数。']),
section('3. molto / tanto / troppo：副词和数量词要分开',['修饰动作或形容词时通常不变：Studio molto；molto buono；troppo caro。修饰名词表示数量时，要配合：molto pane、molta acqua、molti libri、molte persone。tanto/troppo 也有相似的数量配合。','tantissimo 是加强“非常”的表达；un sacco、da morire 很口语。per niente 通常放在否定句里：Non mi piace per niente。不要把太热与很多热混成一种句式。'])
],[question('礼貌','“我想要一杯咖啡”更委婉选？',['Vorrei un caffè','Sono un caffè','Ho volere un caffè'],0,'Vorrei 是常用礼貌请求形式。'),question('情态','Posso ___ un caffè?',['ho','avere','ha'],1,'potere 后接不定式 avere。'),question('量词','“一杯水”选？',['un bicchiere d’acqua','un bicchiere acqua','una bicchiere d’acqua'],0,'bicchiere 阳性，后用 di/d’。'),question('副词','“非常好吃”（la pasta）选？',['molta buona','molto buona','molte buona'],1,'molto 修饰形容词时不变；buona 跟 pasta 配合。'),question('数量','“很多水”选？',['molta acqua','molti acqua','molte acqua'],0,'molto 修饰阴单名词 acqua 时变成 molta。'),question('程度','“太贵了”选？',['È troppo caro','È troppi caro','È tanta caro'],0,'troppo 修饰形容词 caro 时不变。'),question('否定程度','“一点也不喜欢”选？',['Mi piace per niente','Non mi piace per niente','Non mi piacciono per niente leggere'],1,'non…per niente 构成否定加强。')]);

lesson(13,6,[11,12],'piacere 与 mancare：主语是“被喜欢/被想念的东西”','把“我喜欢披萨”暂时理解为“披萨让我喜欢”。',[
section('1. 先找真正的主语',['Mi piace la pizza 中，la pizza 是语法主语（让人喜欢的东西），mi 表示“对我来说”。所以不能因为中文“我喜欢”就写成 io piace。','喜欢单数事物或做一件事：piace。喜欢复数事物：piacciono。动词由被喜欢的东西决定，而不是由喜欢者决定。']),
section('2. 单数、复数、不定式','按第三列判断动词。',table(['表达','中文','决定因素'],[['Mi piace la pizza.','我喜欢披萨','pizza 单数'],['Mi piacciono gli spaghetti.','我喜欢细面','spaghetti 复数'],['Mi piace leggere.','我喜欢读书','不定式动作作为整体'],['Ti piace il caffè?','你喜欢咖啡吗','caffè 单数'],['A Maria piacciono i fiori.','Maria 喜欢花','fiori 复数']])),
section('3. 代词与接话方式',['mi=对我；ti=对你；gli=对他；le=对她；ci=对我们；vi=对你们；gli=对他们/她们（常见用法）。这些是此结构中的间接宾语代词，和直接宾语不能混作一表。','Mi piace… 的“我也喜欢”是 Anche a me。Non mi piace… 的“我也不喜欢”是 Neanche a me。普通 Abito a Milano 的“我也是”才是 Anch’io。否定放在组合前：Non mi piace。']),
section('4. mancare 的方向要反过来理解',['Mi manca mia madre = 我想妈妈；manca 的主语是 mia madre。Mi mancano i miei amici = 我想朋友们；朋友们是复数。','Mi manchi = 你让我感到缺失，也就是“我想你”。这里主语是 tu，所以动词是 manchi；不是“你想我”。表示实际缺物也同理：Manca una penna / Mancano due penne。'])
],[question('单复数','Mi ___ gli spaghetti.',['piace','piacciono','piaccio'],1,'spaghetti 是复数主语。'),question('不定式','Mi ___ leggere.',['piacciono','piace','piaci'],1,'不定式动作作为整体用单数 piace。'),question('喜欢者','“你喜欢咖啡吗”选？',['Tu piace il caffè?','Ti piace il caffè?','Ti piacciono il caffè?'],1,'ti 表“对你”，caffè 为单数。'),question('接话','Mi piace la pizza. — 我也喜欢。',['Anch’io（此题最佳）','Anche a me','Anche mi'],1,'piacere 的接话用 Anche a me。'),question('否定接话','Non mi piace. — 我也不喜欢。',['Neanche a me','Anche io sì','Neanche mi'],0,'否定附和用 Neanche a me。'),question('mancare','Mi manchi 的意思？',['你想我','我想你','我失去了一个东西'],1,'tu 是主语：你使我想念，因此“我想你”。'),question('缺少','___ due asciugamani.',['Manca','Mancano','Manco'],1,'two towels 复数，用 mancano。'),question('辨代词','Mi piace 的 mi 在这句话中是？',['间接宾语，对我','句子主语','冠词'],0,'被喜欢的东西才是主语。')]);

lesson(14,7,[13,27],'物主形容词：我的、你的、他们的','跟“谁拥有”选人称，跟“拥有什么”选词尾。',[
section('1. 分两步决定形式',['先看主人：我的=mio 系、你的=tuo 系、他/她的=suo 系。再看被拥有的名词：il mio libro，la mia casa，i miei libri，le mie case。','说话者是女性也不影响 libro 用 mio；拥有物的语法性别才决定词尾。suo 可以是他的也可以是她的，不能只凭 suo 判断主人性别。']),
section('2. 全表','loro 作为物主词不变，但前面冠词仍要配合名词。',table(['主人','阳单','阴单','阳复','阴复'],[['我','mio','mia','miei','mie'],['你','tuo','tua','tuoi','tue'],['他/她','suo','sua','suoi','sue'],['我们','nostro','nostra','nostri','nostre'],['你们','vostro','vostra','vostri','vostre'],['他们/她们','loro','loro','loro','loro']])),
section('3. 通常需要冠词',['通常是“冠词 + 物主词 + 名词”：il mio libro、la tua macchina、il suo amico。也可有不定冠词：un mio amico = 我的一个朋友。','身份/职业作表语时常不加冠词：Sono studente。特指某人时用名词短语：È il mio cantante preferito。不能总结成“è 后永远要加冠词”或“职业永远不能有冠词”。']),
section('4. 亲属称谓的例外',['单数、未加额外修饰的亲属称谓，通常省冠词：mio padre、mia madre、mio fratello。复数恢复冠词：i miei fratelli。','loro 不省：il loro padre。带形容词或昵称/变体可能恢复冠词：la mia cara sorella、il mio fratellino。把“所有家庭成员永远省冠词”删掉，记清这几种常见情况。'])
],[question('配合','女性说“我的书（libro）”选？',['la mia libro','il mio libro','il mia libro'],1,'mio 跟阳性 libro 配合，与说话人性别无关。'),question('复数','“我的女性朋友们”选？',['le mie amiche','le miei amiche','i miei amiche'],0,'amiche 阴复数，用 le mie。'),question('loro','“他们的房子”选？',['la lora casa','la loro casa','il loro casa'],1,'loro 不变，冠词按 casa 用 la。'),question('亲属','“我父亲”一般选？',['mio padre','il mio padre 是本课默认','mia padre'],0,'单数简单亲属称谓通常省冠词。'),question('亲属复数','“我的兄弟们”选？',['miei fratelli','i miei fratelli','il mio fratelli'],1,'复数亲属名词前恢复冠词。'),question('loro 例外','“他们的父亲”选？',['loro padre','il loro padre','il lori padre'],1,'loro + 亲属单数仍保留冠词。'),question('身份','“我是学生”最基础说法？',['Sono studente','È il mio studente 意思相同','Ho studente'],0,'职业/身份的简单表语常不加冠词。')]);

lesson(15,7,[14],'购物：部分冠词与 ci 代地点','说“一些面包”，也能把“去健身房”简洁接下去。',[
section('1. 部分冠词表示不确定的量',['Compro del pane = 我买一些面包。del 在这里不是“某个东西的”所属关系，而是“一些”。形状虽然与 di+冠词一致，用途要看句子。','不可数或当作整体的食物常用单数部分冠词；可数复数表示“一些”：dei libri、degli amici、delle mele。']),
section('2. 形式与冠词规则一致','先看后面名词需要 il/lo/l’/la/i/gli/le 的哪一种。',table(['对应冠词','部分冠词','例子'],[['il / lo','del / dello','del pane / dello zucchero'],['l’','dell’','dell’acqua'],['la','della','della carne'],['i / gli / le','dei / degli / delle','dei libri / degli amici / delle mele']])),
section('3. 地点与商店',['in farmacia、in libreria、in pescheria；dal fruttivendolo 表示到果蔬商那里。词库包含各商店名称与买什么的例句。','Vado in palestra domani. → Ci vado domani. ci 可代替已经提到的地点“去那里”。这里 ci 不是“我们”的反身代词；同一个小词在不同句子里功能不同。'])
],[question('不可数','“一些面包”选？',['del pane','dei pane','delle pane'],0,'pane 对应 il，所以用 del。'),question('元音','“一些水”选？',['della acqua','dell’acqua','degli acqua'],1,'acqua 元音开头，对应 l’，用 dell’。'),question('阳复数','“一些朋友（男）”选？',['dei amici','degli amici','delle amici'],1,'amici 阳复、元音开头，用 degli。'),question('阴复数','“一些苹果”选？',['delle mele','degli mele','del mele'],0,'mele 阴复数，用 delle。'),question('地点 ci','Vai in palestra? — Sì, ___ vado.',['mi','ci','lo'],1,'ci 在此代替 in palestra。'),question('词义','libreria 和 biblioteca 分别是？',['图书馆/书店','书店/图书馆','两者都只指图书馆'],1,'libreria 常指书店，也可指书架；biblioteca 指图书馆。')]);

lesson(16,8,[16],'情态动词与 sapere：想、能、必须、会','第二个动词用原形，前面一个按主语变位。',[
section('1. 四个意思分开',['voglio=我想；posso=我能/获准；devo=我必须；so=我知道/我会（技能）。So nuotare 强调掌握技能；Posso nuotare 强调现在条件或许可允许。','Voglio studiare / Posso studiare / Devo studiare / So parlare italiano。第二个动词保留不定式，中间不加 a。']),
section('2. 完整变位','注意 vuole、può 的拼写，以及 sappiamo、vogliamo 的双写与组合。',conjugation(['sapere','potere','dovere','volere'],['so,sai,sa,sappiamo,sapete,sanno','posso,puoi,può,possiamo,potete,possono','devo,devi,deve,dobbiamo,dovete,devono','voglio,vuoi,vuole,vogliamo,volete,vogliono'])),
section('3. 礼貌请求与否定',['Posso avere un caffè? 我可以要一杯咖啡吗？Mi può dire…? 您能告诉我……吗？尊称 Lei 用 può；tu 用 puoi。','Non posso uscire = 我不能出门。不要用 non 去插在不定式后。否定整件事时，先把 non 放在变位动词前。'])
],[question('技能','“我会游泳”（学会了）选？',['So nuotare','Sono nuotare','So a nuotare'],0,'sapere + 不定式可表会某项技能。'),question('许可','“我可以进来吗？”选？',['Posso entrare?','So entrare?','Devo entrare?'],0,'问许可用 potere。'),question('必须','noi + dovere =？',['devono','dobbiamo','deviamo'],1,'noi 为 dobbiamo。'),question('想要','lui + volere =？',['vuole','vuola','vogliamo'],0,'第三人称单数 vuole。'),question('变位','noi + sapere =？',['sappiamo','sapiamo','sanno'],0,'sappiamo 有双 p。'),question('不定式','Voglio ___ italiano.',['parlo','parlare','a parlare'],1,'情态后直接接不定式。'),question('尊称','“您能告诉我吗？”选？',['Mi puoi dire?（尊称）','Mi può dire?','Mi potete dire?（对一人尊称）'],1,'Lei 对应 può。'),question('否定','“我不能出门”选？',['Posso uscire non','Non posso uscire','Non posso esco'],1,'non + 情态变位 + 不定式。')]);

lesson(17,8,[16],'c’è / ci sono：说“有”，再说“在哪里”','区分“存在”与“已经知道的东西的位置”。',[
section('1. 有一个和有多个',['C’è un bar. 有一家酒吧。Ci sono due bar. 有两家酒吧。bar 单复数同形，但动词仍受数量影响。','C’è… 常引入新事物；È… 可描述已经明确的主语。C’è un libro sul tavolo=桌上有一本书；Il libro è sul tavolo=那本书在桌上。']),
section('2. 问句、否定和 che','问：Che cosa c’è sul tavolo? 桌上有什么？否定：Non c’è un bar / Non ci sono sedie。che 可连接“有个人正在……”：C’è un uomo che dorme。',null,[['C’è una tazza di caffè sul tavolo.','桌上有一杯咖啡。'],['Ci sono due persone che parlano.','有两个人在说话。']]),
section('3. è / sono 与 c’è / ci sono 不可机械替换',['Sono due studenti 可在“他们是谁？”时表示“他们是两名学生”；Ci sono due studenti 表示“有两名学生”。意思不一样。','旧笔记的 tazza sul caffè 容易理解成“杯子在咖啡上面”，在表达“一杯咖啡”时要写 tazza di caffè。'])
],[question('单数','___ un museo.',['C’è','Ci sono','Sono'],0,'单数 un museo 用 c’è。'),question('复数','___ due musei.',['C’è','Ci sono','È'],1,'复数用 ci sono。'),question('同形复数','___ tre bar.',['C’è','È','Ci sono'],2,'bar 虽不变，tre 表示复数。'),question('位置','“那本书在桌上”选？',['Il libro è sul tavolo','Il libro c’è sul tavolo 是最基础句型','Il libro sono sul tavolo'],0,'已知主语的位置用 essere。'),question('否定','“没有椅子”选？',['Non ci sono sedie','Ci non sono sedie','Non c’è sedie'],0,'non 在 ci sono 前，sedie 复数。'),question('关系句','“有个正在睡觉的男人”选？',['C’è un uomo che dorme','C’è un uomo dormire','Ci sono un uomo che dorme'],0,'单数 c’è + 名词 + che + 变位动词。')]);

lesson(1,1,[1,2],'发音从零：字母怎么变成声音','先掌握能帮助你自己读词的规则，再跟读词卡。',[
section('1. 元音要清楚，重音要听出来',['意大利语 a、e、i、o、u 一般都要清楚地读。a 接近“啊”，i 接近“衣”，u 接近“乌”；e 和 o 各有开口、闭口两类。中文近似音只用来入门，具体发音请反复听意大利语朗读。','多数词的重音在倒数第二音节，但不是绝对规则。不要把单词两边加上斜杠就当成音标。caffè、città 等词末重音在拼写中标出，写作时要保留。']),
section('2. c / g：看后面的字母', 'c、g 在 a/o/u 前是硬音；在 e/i 前是软音。h 不独立发音，它在 che/chi/ghe/ghi 中帮助保留硬音。',table(['拼写','发音提示','例词'],[['ca / co / cu','c 为 [k]','casa, cono, cuore'],['ce / ci','c 为 [tʃ]','cena, cinema'],['che / chi','仍为 [k]','anche, chi'],['ga / go / gu','g 为 [ɡ]','gatto, gonna, gusto'],['ge / gi','g 为 [dʒ]','gentile, giorno'],['ghe / ghi','仍为 [ɡ]','spaghetti, funghi']]),[['Casa e cena.','房子与晚餐。']]),
section('3. 双辅音、r、s、z',['penna、gatto、bocca 的双辅音要比单辅音停留更久，不能当作随手重复的字母。r 通常需要舌尖振动；不要用英语 r 的卷舌方式替代。','s 和 z 不总是只有一种发音，不能只凭“在元音中间”就断定全部读法。先跟读 sera、rosso、zaino、zucchero。gn（如 bagno）和 gli（如 famiglia）是整组声音，先整体模仿。']),
section('4. h 与外来字母',['h 在 ho、hai、ha、hanno 中不单独发音，却能区分词义，听写时仍必须写。','J/K/W/X/Y 多见于外来词和专名：Juventus、koala、Walter、xilofono、yogurt。W、J 等在不同来源的名字里读法可能不同，不能用一个规则套全部外来词。'],null,[['Ho una penna.','我有一支笔。'],['Il gatto è nero.','猫是黑色的。']])
],[question('元音','词卡中的 /casa/ 能直接当作标准音标吗？',['不能，那只是拼写','能，斜杠内都是音标','意大利语不需要发音'],0,'字母拼写不等于国际音标；新版已移除旧版伪音标。'),question('硬软 c','cena 中 c 的音是？',['[k]','[tʃ]','[s]'],1,'c 在 e 前是软音 [tʃ]。'),question('h','chi 中 h 的作用是？',['独立读 h','保留 c 的硬音 [k]','取消元音 i'],1,'chi 的 c 保持 [k]；h 不单独发音。'),question('硬软 g','funghi 中 ghi 的 g 是？',['[dʒ]','[ɡ]','[ʃ]'],1,'gh 在 i 前保持硬音 [ɡ]。'),question('双辅音','penna 的 nn 应怎样处理？',['比单 n 停留更久','完全不发音','读成两个汉字'],0,'双辅音时长有区别，要跟读练习。'),question('拼写','“我有”的拼写是？',['o','ho','oh'],1,'ho 来自 avere，h 虽不发音但不能省。'),question('重音','哪一个写法正确？',['caffe','caffè','caffé 是唯一正确形式'],1,'标准拼写是 caffè，词尾重音要保留。')]);

lesson(2,1,[2,9,27],'第一句话：我是、有、叫什么','认识人称、完整变位和自我介绍的句子结构。',[
section('1. 什么叫“变位”',['中文“我有、你有、他有”的“有”不变；意大利语要变成 ho、hai、ha。看到不定式 avere，先找主语，再选择相应形式。','io=我、tu=你、lui=他、lei=她、noi=我们、voi=你们、loro=他们/她们。尊称 Lei 用第三人称单数。主语常可省略，因为动词词尾能提示人称。']),
section('2. 三套完整形式','先横向对比，再用自己的名字和年龄代入。',conjugation(['essere 是/在','avere 有','chiamarsi 叫作'],['sono,sei,è,siamo,siete,sono','ho,hai,ha,abbiamo,avete,hanno','mi chiamo,ti chiami,si chiama,ci chiamiamo,vi chiamate,si chiamano'])),
section('3. 自我介绍依次说什么',['Mi chiamo + 名字。Sono + 国籍/身份。Ho + 数字 + anni。年龄用 avere，不用 essere；“我二十岁”是 Ho venti anni。','Di dove sei? 问来自哪里；Sono di + 城市。Da dove vieni? 也可问来源，答 Vengo da + 城市。住在某城用 Abito a…，国籍和居住地不是同一件事。'],null,[['Mi chiamo Lin. Sono cinese. Ho ventidue anni.','我叫 Lin，是中国人，二十二岁。'],['Sono di Shanghai, ma abito a Milano.','我来自上海，但住在米兰。']]),
section('4. 否定、疑问与配合',['基础否定是在变位动词前加 non：Non sono italiano。反身/代词句中是 Non mi chiamo Marco，non 在整个代词+动词组合前。','普通陈述句常为“主语 + 动词 + 其他内容”。意大利语问句不需要英语式 do；可用疑问词或语调提问：Sei italiano? 国籍词要配合：italiano/italiana，cinese 男女同形，复数 cinesi。'])
],[question('人称','“我们是”选？',['noi sono','noi siamo','noi siete'],1,'noi 对应 siamo。'),question('年龄','“我二十二岁”选？',['Sono ventidue anni','Ho ventidue anni','Mi chiamo ventidue anni'],1,'年龄用 avere + anni。'),question('名字','“她叫 Anna”选？',['Si chiama Anna','Mi chiama Anna','Si chiamano Anna'],0,'lei 对应 si chiama。'),question('否定','“我不叫 Marco”选？',['Mi non chiamo Marco','Non mi chiamo Marco','Non chiamo mi Marco'],1,'non 放在代词+动词之前。'),question('来源','“我来自上海”选？',['Sono a Shanghai','Sono di Shanghai','Sono in Shanghai'],1,'essere di 表示籍贯；essere a 表示所在位置。'),question('居住','“我住在米兰”选？',['Abito a Milano','Abito di Milano','Ho Milano'],0,'城市前常用 a。'),question('尊称','对一位老师用“您有”选？',['Lei avete','Lei hai','Lei ha'],2,'尊称 Lei 搭配第三人称单数 ha。'),question('国籍','女性说“我是意大利人”选？',['Sono italiano','Sono italiana','Ho italiana'],1,'italiana 为阴性单数。')]);

lesson(3,2,[3],'疑问词：问人、时间、地点、数量','把疑问词和你已经认识的动词组合起来。',[
section('1. 先确定你想问哪类信息','dove 问地点；quando 问时间；chi 问人；come 问方式/状态；perché 问原因，也能在回答中表示“因为”。che/cosa/che cosa 都可表示“什么”。',table(['目标','问句','意思'],[['地点','Dove abiti?','你住哪里？'],['时间','Quando parti?','你何时出发？'],['原因','Perché studi?','你为什么学习？'],['人物','Chi è?','是谁？'],['行为','Che cosa fai?','你在做什么？'],['状态','Come stai?','你好吗？']])),
section('2. quanto 要看有没有修饰名词',['Quanto costa? 中 quanto 问价格，用这个固定问法即可。修饰名词时，要配合名词的性与数：quanto pane、quanta acqua、quanti amici、quante amiche。','不要把“多少钱”的固定问句规则直接套到所有数量问题。先找名词，再选四种形式。']),
section('3. quale 只分单复数',['quale + 单数，quali + 复数，不像 quanto 那样分四种。Quale gelato vuoi? 哪个冰淇淋？Quali gusti preferisci? 哪些口味？','Qual è…? 的 qual 不带撇号；Dov’è / Com’è 的 è 前可发生省音，要保留 è 的重音。Di chi è? 问“是谁的”，A chi scrivi? 问“写给谁”。'])
],[question('地点','问住在哪里选？',['Dove abiti?','Quando abiti?','Chi abiti?'],0,'dove 问地点。'),question('原因','perché 可以表示？',['只能为什么','为什么，也可表示因为','只能什么'],1,'例如 Perché studi? Perché mi piace.。'),question('数量','___ acqua vuoi?',['Quanto','Quanta','Quanti'],1,'acqua 阴性单数，用 quanta。'),question('数量','___ amici hai?',['Quanti','Quante','Quanto'],0,'amici 阳性复数，用 quanti。'),question('选择','___ gusti preferisci?',['Quale','Quali','Quala'],1,'gusti 为复数，用 quali。'),question('所有者','“这是谁的书？”选？',['Di chi è questo libro?','A chi è questo libro?','Dove è questo libro?'],0,'di chi 表示谁的。'),question('拼写','“你的名字是什么？”选？',['Qual’è il tuo nome?','Qual è il tuo nome?','Quale è sempre obligatorio'],1,'qual è 不写撇号。')]);

lesson(4,2,[2,3,6],'名词性别与复数：规则和例外','记住“词 + 冠词 + 复数”，不要只记一个孤立中文义。',[
section('1. 语法性别不是自然性别',['每个意大利语名词有语法性别。la persona 是阴性名词，无论指男性还是女性；il nome 虽以 -e 结尾，却是阳性。','-o 多为阳性、-a 多为阴性、-e 可阳可阴。-zione 名词通常为阴性，如 la nazione；但别把词尾提示当作绝对规律。il caffè、il fiore、il sale、la mano 都要单独记。']),
section('2. 最常见的单复数变化','变化的是名词词尾，冠词也必须一起变。',table(['单数','复数','说明'],[['il ragazzo','i ragazzi','-o → -i'],['la ragazza','le ragazze','-a → -e'],['lo studente','gli studenti','-e → -i，仍为阳性'],['la notte','le notti','-e → -i，仍为阴性'],['la mano','le mani','阴性但以 -o 结尾'],['l’uomo','gli uomini','不规则'],['la foto','le foto','缩写通常不变'],['la città / il caffè / il re','le città / i caffè / i re','词尾重音、单音节等常不变']])),
section('3. 拼写上的特殊复数',['-co/-go 的复数存在词汇性例外。parco→parchi、lago→laghi；amico→amici、medico→medici。不能把重音位置总结当成无例外算法，最好连复数一起背。','-cia/-gia 中 i 不重读时，前面为元音一般保留 i，前面为辅音一般去 i：camicia→camicie，arancia→arance。farmacia 的 i 本身重读，所以是 farmacie，不能套“前面辅音就删 i”。','-ista 常按性别变化：il turista→i turisti，la turista→le turiste。性别和复数都要检查。'])
],[question('性别','la mano 的复数是？',['i mani','le mani','le mane'],1,'mano 为阴性，复数 mani，冠词 le。'),question('复数','lo studente 的复数是？',['i studente','gli studenti','le studente'],1,'studente 是阳性，复数 studenti，st 开头用 gli。'),question('例外','il fiore 的性别是？',['阳性','阴性','两者都不是'],0,'fiore 为阳性，-e 结尾不能判定性别。'),question('不变词','la città 的复数是？',['le cittè','le città','i città'],1,'词尾重音名词通常保持同形。'),question('特殊复数','amico / parco 的复数是？',['amichi / parci','amici / parchi','amici / parci'],1,'这两个词要连着具体复数记。'),question('重读 i','farmacia 的复数是？',['farmace','farmacie','farmacii'],1,'farmacìa 的 i 重读，保留成 farmacìe。'),question('不规则','l’uomo 的复数是？',['gli uomini','i uomi','gli uomos'],0,'uomo → uomini，元音开头用 gli。')]);

lesson(5,2,[6,18],'冠词：il、lo、la 和 un、uno、una','先看性别与数量，再看下一个词的开头。',[
section('1. 什么时候用定冠词或不定冠词',['定冠词类似“这个/那些已经明确的东西”：il libro。第一次引入“一个”通常用不定冠词：un libro。中文不总需要“这个/一个”，所以不能逐字翻译判断。','下面“开头”指冠词之后紧接的词。il bravo studente 与 lo studente 不同，是因为紧接的 bravo 与 studente 开头不同。']),
section('2. 定冠词全表','把“特殊开头”视为一组：s + 辅音、z、gn、ps、x 等，常见例子 lo studente、lo zaino、lo psicologo。',table(['名词类型','单数','复数','例子'],[['阳性普通辅音','il','i','il libro / i libri'],['阳性特殊开头','lo','gli','lo zaino / gli zaini'],['阳性元音','l’','gli','l’amico / gli amici'],['阴性辅音','la','le','la casa / le case'],['阴性元音','l’','le','l’amica / le amiche']])),
section('3. 不定冠词：撇号最容易写错','un 是阳性元音和普通辅音前的形式，不加撇号；un’ 是阴性 una 的省音。不要把所有元音开头都写成 un’。',table(['类型','形式','例子'],[['阳性普通辅音/元音','un','un libro / un amico'],['阳性特殊开头','uno','uno studente / uno zaino'],['阴性辅音','una','una casa'],['阴性元音','un’','un’amica']])),
section('4. 复数“几个/一些”怎么说','un/uno/una 本身没有对应的普通复数形式。可以用部分冠词 dei/degli/delle 或 alcuni/alcune 表达“一些”；部分冠词会在购物单元展开。')
],[question('定冠词','___ zaino 是“那个背包”。',['il','lo','la'],1,'z 开头的阳性单数用 lo。'),question('定冠词复数','l’amico 的复数？',['i amici','gli amici','le amici'],1,'阳性元音开头复数用 gli。'),question('阴复数','___ case',['le','gli','la'],0,'case 为阴性复数，用 le。'),question('不定冠词','一个男朋友（amico）选？',['un’amico','uno amico','un amico'],2,'阳性元音前 un，无撇号；这里“朋友”不是恋人专称。'),question('不定冠词','一个女性朋友（amica）选？',['un amica','un’amica','uno amica'],1,'阴性元音前用 un’。'),question('特殊开头','一个学生选？',['un studente','uno studente','una studente'],1,'st 为 s+辅音，阳性单数用 uno。'),question('紧邻词','“那位优秀学生”选？',['lo bravo studente','il bravo studente','l’ bravo studente'],1,'冠词后紧邻 bravo，是普通辅音开头。')]);

lesson(6,3,[4,13],'规则现在时：三类词尾与 -isc-','从不定式找到词干，再接上主语需要的词尾。',[
section('1. 不定式和变位形式是什么',['mangiare=“吃”这个动作原形；mangio=“我吃”。先去掉 -are，得到 mangi-，再按人称加词尾。leggere 去 -ere、dormire 去 -ire，方法一样。','现在时可以说现在、习惯，也可配 domani 表示已安排的将来。本单元先练最常用的“我/你/我们每天做什么”。']),
section('2. 三类完整变位','按行读一遍，再遮住右侧自己说。',conjugation(['mangiare','leggere','dormire'],['mangio,mangi,mangia,mangiamo,mangiate,mangiano','leggo,leggi,legge,leggiamo,leggete,leggono','dormo,dormi,dorme,dormiamo,dormite,dormono'])),
section('3. -IRE 还有 -isc- 这一组',['capire、finire、pulire、preferire、costruire、spedire 在 io/tu/lui-lei/loro 形式加入 -isc-；noi/voi 不加入。不是每个 -ire 都这样，dormire 就不加。','以 preferire 为例：preferisco、preferisci、preferisce、preferiamo、preferite、preferiscono。不要写成 preferisciamo。'],null,[['Preferisco il tè, ma dormo presto.','我更喜欢茶，但我很早睡觉。'],['Noi capiamo la regola.','我们理解这条规则。']]),
section('4. 拼写和实际用法',['cercare→cerchi、pagare→paghi 中 h 保留硬音；mangiare→mangi、mangiamo，不重复写两个 i。遇到新词，要核对词典变位，不能只按拼写机械拼接。','练句时用一个完整主语起步：Io mangio / Noi leggiamo / Loro dormono。熟悉后可省略主语。'])
],[question('现在时','io + mangiare =？',['mangio','mangi','mangia'],0,'io 形式 mangio。'),question('现在时','noi + leggere =？',['leggete','leggiamo','leggono'],1,'noi 的 -ERE 词尾为 -iamo。'),question('现在时','loro + dormire =？',['dormiamo','dormano','dormono'],2,'规则 -IRE 的 loro 形式用 -ono。'),question('-isc-','io + preferire =？',['prefero','preferisco','preferiamo'],1,'preferire 属 -isc- 组。'),question('-isc-','noi + capire =？',['capisciamo','capiamo','capiscono'],1,'noi 不插入 -isc-。'),question('-isc-','下列哪个不按 -isc- 变位？',['finire','pulire','dormire'],2,'dormire 是 dormo/dormi，不加 -isc-。'),question('拼写','tu + cercare =？',['cerci','cerchi','cercahi'],1,'ch 保持 c 的硬音。'),question('拼写','tu + mangiare =？',['mangii','mangi','manghi'],1,'直接写 mangi，不重复 i。')]);

lesson(7,3,[5,16],'常见不规则现在时：完整表格','这些高频动词靠成组练习，不靠套一个规则。',[
section('1. 去、待、做','请先拿下我/你/我们，再补齐其余人称。',conjugation(['andare','stare','fare'],['vado,vai,va,andiamo,andate,vanno','sto,stai,sta,stiamo,state,stanno','faccio,fai,fa,facciamo,fate,fanno'])),
section('2. 说、喝、给、来、出门','dare 的第三人称 dà 带重音，以区别介词 da。',conjugation(['dire','bere','dare','venire','uscire'],['dico,dici,dice,diciamo,dite,dicono','bevo,bevi,beve,beviamo,bevete,bevono','do,dai,dà,diamo,date,danno','vengo,vieni,viene,veniamo,venite,vengono','esco,esci,esce,usciamo,uscite,escono'])),
section('3. 固定搭配连着记',['fare colazione=吃早餐；fare i compiti=做作业；fare la doccia=洗淋浴。这里的 fare 不能逐字硬译成“制造”。','andare a Roma / andare in Italia 是去某地；venire da Roma 是从罗马来。方向和来源不同，介词也不同。'],null,[['Vado a scuola e faccio i compiti.','我去上学并做作业。'],['Beviamo un caffè e poi usciamo.','我们喝杯咖啡，然后出门。']])
],[question('andare','noi + andare =？',['vanno','andiamo','vadiamo'],1,'noi 为 andiamo。'),question('stare','voi + stare =？',['state','stanno','stiamo'],0,'voi 为 state。'),question('fare','loro + fare =？',['fanno','faccono','fate'],0,'loro 为 fanno。'),question('dire','voi + dire =？',['dicete','dite','dicono'],1,'dire 的 voi 为 dite。'),question('bere','noi + bere =？',['beiamo','beviamo','beriamo'],1,'noi 为 beviamo。'),question('dare','“他给”选？',['da','dà','do'],1,'dà 带重音；da 是介词。'),question('venire','loro + venire =？',['venono','vengono','venite'],1,'loro 为 vengono。'),question('uscire','io + uscire =？',['usco','esco','uscisco'],1,'io 为 esco。')]);

lesson(8,3,[4],'动词 + a + 不定式','“开始学、继续读、学会做”中的第二个动作保留原形。',[
section('1. 一句话里两个动作怎样连接',['Comincio a studiare 中 comincio 随“我”变位，studiare 保留不定式。你可以先把整句理解为“我开始 + 去学习”。中间的 a 是这个动词搭配要求的，不能漏掉。','同理：continuare a、andare a、imparare a、insegnare a、abituarsi a、riuscire a、provare a。这里把这些课堂搭配整体记住，不把 a 误认为所有“第二个动词”的通用连接法。']),
section('2. 每个搭配表达什么','先看第一列动词的意思，再选择你想做的动作。',table(['搭配','例句','含义'],[['cominciare a','Comincio a studiare.','开始学习'],['continuare a','Continuo a leggere.','继续读'],['imparare a','Imparo a cucinare.','学做饭'],['insegnare a','Mi insegna a suonare.','教我演奏'],['abituarsi a','Mi abituo a vivere qui.','习惯在这里生活'],['riuscire a','Riesco a capire.','能够理解'],['provare a','Provo a telefonare.','试着打电话']])),
section('3. 与情态动词区分',['Voglio studiare、Posso entrare、Devo partire 的中间没有 a。为什么？因为 volere/potere/dovere 的结构本来就是“情态动词 + 不定式”。','因此要逐个记搭配：comincio a studiare，却是 voglio studiare。不要把每个“想/能/开始”都写成同一种形式。'])
],[question('结构','“我开始学习”选？',['Comincio studiare','Comincio a studiare','Comincio a studio'],1,'cominciare a + 不定式。'),question('不定式','Continuo a ___ .',['leggo','leggere','leggi'],1,'第二个动作保留不定式 leggere。'),question('学会','“我学习做饭”选？',['Imparo a cucinare','Imparo cucino','Imparo di cucinare'],0,'imparare a + 不定式。'),question('习惯','“我习惯在这里生活”选？',['Abituo vivere qui','Mi abituo a vivere qui','Mi abituo vivo qui'],1,'abituarsi 需要反身代词，后接 a + 不定式。'),question('能力','Riesco ___ capire.',['a','di','不需要介词'],0,'riuscire a 是固定搭配。'),question('对比','“我想学习”选？',['Voglio a studiare','Voglio studio','Voglio studiare'],2,'volere + 不定式，中间无 a。')]);
